mapper.select:
select buss_number, product_code, manage_user_code, sum(task_num) task_num, max(batch_num) batch_num, max(sell_Order_Code) sell_Order_Code
                  , contract_code    contract_code
                  , max(primary_key) primary_key
from ${dynamicTableNameProxy.collaborateProduceDistribute} a
where enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
  and delete_flag = false
  and contract_code = #{data.contractCode}
  and manage_user_code = ${dynamicTableNameProxy.currentCode}
group by buss_number, product_code, manage_user_code, contract_code
